package com.cognia.api.application.service;
import static org.junit.jupiter.api.Assertions.*;
import com.cognia.api.application.port.out.*; import com.cognia.api.domain.model.*; import com.cognia.api.domain.service.*; import java.util.*; import org.junit.jupiter.api.Test;
class DiagnosticServiceTest {
	private final UUID student=UUID.randomUUID(), subject=UUID.randomUUID(), sessionId=UUID.randomUUID(), concept=UUID.randomUUID(), profile=UUID.randomUUID();
	private final Activity diagnostic=activity(Activity.Usage.DIAGNOSTICO), practice=activity(Activity.Usage.PRACTICA);
	private final FakeRepository repo=new FakeRepository(); private final FakeActivities activities=new FakeActivities();
	private DiagnosticService service(){return new DiagnosticService(repo,id->true,new SubjectRepository(){public List<Subject> findAll(){return List.of();}public Optional<Subject> findById(UUID id){return Optional.of(new Subject(id,"S","Subject",null,true));}},activities,new ActivityCorrectionService(),new RuleBasedMasteryPolicy(Map.of(1,1d,2,1.5d,3,2d)));}
	@Test void cannotFinishWithoutAnswersAndLeavesSessionInProgress(){repo.session=new DiagnosticSession(sessionId,student,subject,"EN_PROGRESO",null,null);assertThrows(InvalidPracticeRequestException.class,()->service().finish(student,sessionId));assertEquals("EN_PROGRESO",repo.session.state());assertFalse(repo.profileCompleted);}
	@Test void rejectsAnsweringTheSameActivityTwice(){repo.session=new DiagnosticSession(sessionId,student,subject,"EN_PROGRESO",null,null);repo.answers.add(new DiagnosticAnswer(UUID.randomUUID(),sessionId,diagnostic.id(),diagnostic.options().get(0).id(),null,true,null));assertThrows(DiagnosticConflictException.class,()->service().answer(student,sessionId,diagnostic.id(),diagnostic.options().get(0).id(),null,null));}
	@Test void rejectsActivitiesOutsideDiagnosticUsage(){repo.session=new DiagnosticSession(sessionId,student,subject,"EN_PROGRESO",null,null);activities.items.put(practice.id(),practice);assertThrows(InvalidPracticeRequestException.class,()->service().answer(student,sessionId,practice.id(),practice.options().get(0).id(),null,null));}
	@Test void recordsMasteryHistoryWithDiagnosticOriginAndSessionReference(){repo.session=new DiagnosticSession(sessionId,student,subject,"EN_PROGRESO",null,null);repo.answers.add(new DiagnosticAnswer(UUID.randomUUID(),sessionId,diagnostic.id(),diagnostic.options().get(0).id(),null,true,null));activities.items.put(diagnostic.id(),diagnostic);var done=service().finish(student,sessionId);assertEquals("COMPLETADA",done.state());assertTrue(repo.profileCompleted);assertEquals(MasteryChangeSource.DIAGNOSTICO,repo.historySource);assertEquals(sessionId,repo.historySession);assertEquals(100d,done.score());}
	private Activity activity(Activity.Usage usage){return new Activity(UUID.randomUUID(),concept,"A1","Question",null,1,usage,Activity.Type.SELECCION_MULTIPLE,true,List.of(new ActivityOption(UUID.randomUUID(),"yes",true,null),new ActivityOption(UUID.randomUUID(),"no",false,null)),List.of());}
	private class FakeActivities implements ActivityRepository {final Map<UUID,Activity> items=new HashMap<>();public List<Activity> findPracticeByConcept(UUID id,Integer d){return List.of();}public List<Activity> findDiagnosticBySubject(UUID id){return items.values().stream().filter(a->a.usage()==Activity.Usage.DIAGNOSTICO).toList();}public Optional<Activity> findById(UUID id){return Optional.ofNullable(items.get(id));}}
	private class FakeRepository implements DiagnosticRepository {DiagnosticSession session;boolean profileCompleted;final List<DiagnosticAnswer> answers=new ArrayList<>();MasteryChangeSource historySource;UUID historySession;public Optional<DiagnosticSession> findInProgress(UUID s,UUID c){return Optional.empty();}public boolean hasCompleted(UUID s,UUID c){return false;}public DiagnosticSession saveSession(DiagnosticSession s){session=s;return s.id()==null?new DiagnosticSession(sessionId,s.studentId(),s.subjectId(),s.state(),s.score(),s.closedAt()):s;}public Optional<DiagnosticSession> findSession(UUID id){return Optional.ofNullable(session);}public List<DiagnosticAnswer> answers(UUID id){return answers;}public DiagnosticAnswer saveAnswer(DiagnosticAnswer a){answers.add(a);return a;}public UUID ensureProfile(UUID s,UUID c){return profile;}public void completeProfile(UUID id){profileCompleted=true;}public KnowledgeProfile profile(UUID s,UUID c){return null;}public Optional<ConceptMastery> mastery(UUID p,UUID c){return Optional.empty();}public ConceptMastery saveMastery(UUID p,ConceptMastery m){return m;}public void saveHistory(UUID p,UUID c,double previous,double next,MasteryChangeSource source,UUID session){historySource=source;historySession=session;} }
}
